questionvariables.text:
/* Curated [a, x0] pairs: x0 a perfect square so P=(x0, a*sqrt(x0)) is a lattice
   point and m = a/(2*sqrt(x0)) is a controlled fraction. Slopes span 0.25..1.5,
   with m = 1 excluded (so the "run over rise" inverted answer never coincides
   with the correct gradient). */
data : [[1,1],[1,4],[2,4],[2,9],[3,4],[3,9],[3,1]];
pr  : data[rand(length(data))+1];
aa : pr[1];
x0 : pr[2];
r0 : sqrt(x0);            /* integer, since x0 is a perfect square */
y0 : aa*r0;              /* P's y-coordinate (integer) */
m  : aa/(2*r0);          /* true tangent slope f'(x0) - a tidy fraction */
md3 : float(round(1000*m)/1000);   /* m to 3 d.p. for the worked solution */

fdisp : if aa = 1 then sqrt(x) else aa*sqrt(x);   /* display of f(x) */

/* A lattice point exactly on the tangent: stepping +-2*r0 in x moves +-aa in y.
   Prefer the point toward the origin if it stays comfortably on-screen. */
stp : 2*r0;
xg : if x0 - stp >= 1 then x0 - stp else x0 + stp;
yg : if x0 - stp >= 1 then y0 - aa else y0 + aa;
ta1 : [xg, yg];          /* model answer for the drag: a correct Q on the tangent */

/* Off-tangent point for the process-credit test (shift y by 1). */
xb : xg;
yb : yg + 1;
sl_bad : (yb - y0)/(xb - x0);

minv : 1/m;              /* the inverted (run/rise) wrong gradient */

/* Initial Q: horizontal line through P (slope 0) - clearly not the tangent, so a
   do-nothing submission scores zero on the drag. */
qix : xg;
qiy : y0;

/* Board bounds: keep P and the correct Q on screen with padding. */
xmax : max(x0, xg) + 3;
ymax : max(y0, yg) + 3;

feedbackvariables.text:
xq : ans1[1];
yq : ans1[2];
vert : is(abs(xq - x0) < 0.001);
sl : if vert then 0 else (yq - y0)/(xq - x0);

/* Round Q's coordinates to 3 d.p. FIRST, so the slope we mark against is computed
   from exactly the values shown in the readout (snapping is off, so the raw bound
   coordinates carry more precision than the student can see). */
xq : float(round(1000*ans1[1])/1000);
yq : float(round(1000*ans1[2])/1000);
vert : is(abs(xq - x0) < 0.001);
sl : if vert then 0 else (yq - y0)/(xq - x0);
invsl : if is(abs(sl) < 0.001) then 1000000 else 1/sl;
